mapper.select:
SELECT * from (

    SELECT subject_id,name subjectName,code subjectCode,CONCAT(code,' ',full_name) subjectNameBy,`level` from book_subject where  code in(
    SELECT LEFT(bs.code,#{codeNum}) FROM `book_voucher_record` bvr
    LEFT JOIN book_voucher bv on bv.voucher_id = bvr.voucher_id
    LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id
    where bvr.del_flag = '0' and bv.book_id = #{bookId} and bs.is_quantity = 1
    and bv.year_period >= #{startPeriod} and bv.year_period <= #{endPeriod}
    GROUP BY LEFT(bs.code,#{codeNum})
    ) and book_id = #{bookId} and `level` = #{index}+1

)a where 1=1

    and a.level >= #{startLevel}


    and a.level <= #{endLevel}

GROUP BY a.subject_id order BY a.subjectCode

SELECT *,ROUND(debit_total/debitQuantity,2) debitPrice,ROUND(credit_total/creditQuantity,2)creditPrice from ( SELECT '本期合计'summary, IFNULL(SUM(IF(bvr.balance_direction='DEBIT',bvr.quantity,0)),0) debitQuantity, IFNULL(SUM(IF(bvr.balance_direction='CREDIT',bvr.quantity,0)),0) creditQuantity, IFNULL(SUM(bvr.debit),0) debit_total, IFNULL(SUM(bvr.credit),0) credit_total FROM `book_voucher_record` bvr LEFT JOIN book_voucher bv on bv.voucher_id = bvr.voucher_id LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id where bvr.del_flag = '0' and bv.book_id = #{bookId} and bs.code LIKE CONCAT('',(SELECT code from book_subject where subject_id = #{subjectId} and book_id = #{bookId}) ,'%') and bvr.price is not null and bvr.quantity is not null
and bv.year_period = #{currentPeriod}
) a

SELECT *,ROUND(debit_total/debitQuantity,2) debitPrice,ROUND(credit_total/creditQuantity,2)creditPrice from ( SELECT '本年累计'summary, IFNULL(SUM(IF(bvr.balance_direction='DEBIT',bvr.quantity,0)),0) debitQuantity, IFNULL(SUM(IF(bvr.balance_direction='CREDIT',bvr.quantity,0)),0) creditQuantity, IFNULL(SUM(bvr.debit),0) debit_total, IFNULL(SUM(bvr.credit),0) credit_total FROM `book_voucher_record` bvr LEFT JOIN book_voucher bv on bv.voucher_id = bvr.voucher_id LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id where bvr.del_flag = '0' and bv.book_id = #{bookId} and bs.code LIKE CONCAT('',(SELECT code from book_subject where subject_id = #{subjectId} and book_id = #{bookId}) ,'%') and bvr.price is not null and bvr.quantity is not null
and bv.year_period <= #{currentPeriod} and YEAR(year_period) = YEAR(#{currentPeriod})
) a
